from pathlib import Path
import csv,json,hashlib,shutil,math,time
import numpy as np
ROOT=Path(__file__).resolve().parents[2];R=ROOT/'outputs/phase400/phase400_20261031';D=R/'delivery'
def js(p):return json.loads(Path(p).read_text(encoding='utf-8-sig'))
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def csvrows(p):
 with p.open(encoding='utf-8',newline='') as f:return list(csv.DictReader(f))
def writecsv(p,rows):
 keys=list(dict.fromkeys(k for v in rows for k in v))
 with p.open('w',encoding='utf-8',newline='') as f:
  w=csv.DictWriter(f,keys);w.writeheader();w.writerows(rows)
def dump(p,v):p.write_text(json.dumps(v,indent=2,ensure_ascii=False,allow_nan=False),encoding='utf-8')
def close(a,b):assert abs(float(a)-float(b))<1e-8,(a,b)
def metrics(c):
 c=np.array(c,dtype=np.int64);diag=c.diagonal();union=c.sum(0)+c.sum(1)-diag;iou=np.divide(diag,union,out=np.full(3,np.nan),where=union>0)*100;return {'mIoU':float(np.nanmean(iou)),'IoU':iou,'Shadow_IoU':float(iou[2]),'Shadow_recall':100*diag[2]/c.sum(1)[2] if c.sum(1)[2] else None,'nonShadow_FPR':100*c[:2,2].sum()/c[:2,:].sum() if c[:2,:].sum() else None}
